function find_product(string $slug): ?array
{
    foreach (content_products() as $p) {
        if ($p['slug'] === $slug) return $p;
    }
    return null;
}

/** Ürün teknik özellik tabloları (app/products-specs.php). Kodlar ve ölçüler orada düzenlenir. */
function content_specs(string $slug): array
{
    static $all = null;
    if ($all === null) {
        $file = __DIR__ . '/products-specs.php';
        $all = is_file($file) ? (require $file) : [];
    }
    return $all[$slug] ?? [];
}

/** Spec tablosu terimlerini (başlık/renk/caps etiket/açıklama) aktif dile çevirir; bilinmeyen terim/kod/sayı aynen döner. */
function spec_t(string $term): string
{
    static $map = null;
    if ($map === null) {
        $file = __DIR__ . '/spec-i18n.php';
        $map = is_file($file) ? (require $file) : [];
    }
    $l = lang();
    if ($l === 'en') return $term;
    return $map[$term][$l] ?? $term;
}

/** Quality sayfasi icerigi (handbook v5 — kalite kontrol asamalari + urun testleri). */
function content_quality(): array
{
    return [
        'lead' => ['en' => 'Quality controlled at every stage', 'tr' => 'Her aşamada kalite kontrolü', 'zh' => '每一道工序都严格把控品质', 'es' => 'Calidad controlada en cada etapa', 'ru' => 'Контроль качества на каждом этапе', 'fr' => 'La qualité contrôlée à chaque étape', 'pl' => 'Jakość kontrolowana na każdym etapie', 'de' => 'Qualität auf jeder Stufe geprüft', 'he' => 'בקרת איכות בכל שלב'],
        'body' => ['en' => 'Every Redex bottle moves through a multi-stage quality system. It begins at the forming machine and ends with a final QC inspection; in between, an automatic camera photographs each bottle and checks its external and neck-thread dimensions, air bubbles and visual defects, while light and packaging inspections catch any remaining flaws. Non-conforming bottles are separated, and every defect type has its own AQL (Acceptable Quality Level) limit.', 'tr' => 'Her Redex şişesi çok aşamalı bir kalite sisteminden geçer. Şekillendirme makinesinde başlar, son kalite kontrol denetimiyle biter; arada bir otomatik kamera her şişeyi fotoğraflar ve dış ile ağız dişi ölçülerini, hava kabarcıklarını ve görsel kusurları kontrol eder; ışık ve ambalaj denetimleri ise kalan kusurları yakalar. Uygun olmayan şişeler ayrılır ve her kusur türünün kendi AQL (Kabul Edilebilir Kalite Düzeyi) sınırı vardır.', 'zh' => '每一只 Redex 瓶子都要经过多道质量管控。从成型机开始，到最终质检结束；其间，自动相机逐瓶拍照，检查外形与瓶口螺纹尺寸、气泡及外观缺陷，灯检与包装检验再排查其余瑕疵。不合格品被分离，每种缺陷都有各自的 AQL（可接受质量水平）限值。', 'es' => 'Cada botella Redex pasa por un sistema de calidad de varias etapas. Comienza en la máquina de conformado y termina con una inspección final de QC; entremedias, una cámara automática fotografía cada botella y comprueba sus dimensiones externas y de rosca del cuello, las burbujas de aire y los defectos visuales, mientras que las inspecciones de luz y de embalaje detectan cualquier defecto restante. Las botellas no conformes se separan y cada tipo de defecto tiene su propio límite AQL (nivel de calidad aceptable).', 'ru' => 'Каждый флакон Redex проходит многоступенчатую систему качества. Она начинается на формующей машине и заканчивается финальной проверкой QC; между ними автоматическая камера фотографирует каждый флакон и проверяет наружные размеры и размеры резьбы горловины, воздушные пузырьки и визуальные дефекты, а световой и упаковочный контроль выявляют оставшиеся изъяны. Несоответствующие флаконы отделяются, и для каждого типа дефекта установлен свой предел AQL (приемлемый уровень качества).', 'fr' => 'Chaque flacon Redex traverse un système qualité en plusieurs étapes. Il commence à la machine de formage et se termine par un contrôle qualité final ; entre les deux, une caméra automatique photographie chaque flacon et vérifie ses dimensions externes et de filetage du col, les bulles d’air et les défauts visuels, tandis que les contrôles à la lumière et à l’emballage détectent les défauts restants. Les flacons non conformes sont écartés et chaque type de défaut a sa propre limite AQL (niveau de qualité acceptable).', 'pl' => 'Każda butelka Redex przechodzi wieloetapowy system jakości. Zaczyna się na maszynie formującej, a kończy końcową kontrolą QC; pomiędzy nimi automatyczna kamera fotografuje każdą butelkę i sprawdza jej wymiary zewnętrzne oraz gwintu szyjki, pęcherze powietrza i wady wizualne, a kontrola świetlna i pakowania wychwytuje pozostałe usterki. Butelki niezgodne są oddzielane, a każdy typ wady ma własny limit AQL (akceptowalny poziom jakości).', 'de' => 'Jede Redex-Flasche durchläuft ein mehrstufiges Qualitätssystem. Es beginnt an der Formmaschine und endet mit einer finalen QC-Prüfung; dazwischen fotografiert eine automatische Kamera jede Flasche und prüft Außen- und Mündungsgewindemaße, Luftblasen und optische Fehler, während Durchlicht- und Verpackungsprüfung verbleibende Mängel erfassen. Nicht konforme Flaschen werden aussortiert, und jeder Fehlertyp hat seinen eigenen AQL-Grenzwert (Acceptable Quality Level).', 'he' => 'כל בקבוק של Redex עובר מערכת איכות רב-שלבית. היא מתחילה במכונת העיצוב ומסתיימת בבדיקת QC סופית; בין לבין, מצלמה אוטומטית מצלמת כל בקבוק ובודקת את מידותיו החיצוניות ואת מידות תבריג הצוואר, בועות אוויר ופגמים חזותיים, בעוד בדיקות אור ואריזה מאתרות פגמים שנותרו. בקבוקים שאינם תקינים מופרדים, ולכל סוג פגם יש גבול AQL משלו (רמת איכות מקובלת).'],
        'tests_title' => ['en' => 'Quality tests we perform', 'tr' => 'Yaptığımız kalite testleri', 'zh' => '我们开展的质量测试', 'es' => 'Ensayos de calidad que realizamos', 'ru' => 'Испытания качества, которые мы проводим', 'fr' => 'Les essais qualité que nous réalisons', 'pl' => 'Badania jakości, które wykonujemy', 'de' => 'Qualitätsprüfungen, die wir durchführen', 'he' => 'בדיקות האיכות שאנו מבצעים'],
        'tests_intro' => ['en' => 'Beyond in-line inspection, we carry out laboratory product tests to industry, national and relevant international standards:', 'tr' => 'Hat üzeri denetimin ötesinde; sektör, ulusal ve ilgili uluslararası standartlara göre laboratuvar ürün testleri uygularız:', 'zh' => '除在线检验外，我们还按行业、国家及相关国际标准进行实验室产品测试：', 'es' => 'Además de la inspección en línea, realizamos ensayos de producto en laboratorio según normas industriales, nacionales e internacionales pertinentes:', 'ru' => 'Помимо контроля на линии, мы проводим лабораторные испытания изделий по отраслевым, национальным и соответствующим международным стандартам:', 'fr' => 'Au-delà du contrôle en ligne, nous réalisons des essais produit en laboratoire selon les normes industrielles, nationales et internationales pertinentes :', 'pl' => 'Poza kontrolą na linii wykonujemy laboratoryjne badania produktu zgodnie z normami branżowymi, krajowymi i odpowiednimi międzynarodowymi:', 'de' => 'Über die Inline-Kontrolle hinaus führen wir Laborproduktprüfungen nach branchenbezogenen, nationalen und relevanten internationalen Normen durch:', 'he' => 'מעבר לבדיקה בקו הייצור, אנו מבצעים בדיקות מוצר במעבדה לפי תקנים תעשייתיים, לאומיים ובינלאומיים רלוונטיים:'],
        'tests' => [
            ['en' => 'Internal surface hydrolytic resistance test', 'tr' => 'İç yüzey hidrolitik direnç testi', 'zh' => '内表面耐水性测试', 'es' => 'Ensayo de resistencia hidrolítica de la superficie interna', 'ru' => 'Испытание гидролитической стойкости внутренней поверхности', 'fr' => 'Essai de résistance hydrolytique de la surface interne', 'pl' => 'Badanie odporności hydrolitycznej powierzchni wewnętrznej', 'de' => 'Prüfung der hydrolytischen Beständigkeit der inneren Oberfläche', 'he' => 'בדיקת עמידות הידרוליטית של פני השטח הפנימיים'],
            ['en' => 'Thermal shock test', 'tr' => 'Isıl şok testi', 'zh' => '热震测试', 'es' => 'Ensayo de choque térmico', 'ru' => 'Испытание на термоудар', 'fr' => 'Essai de choc thermique', 'pl' => 'Badanie szoku termicznego', 'de' => 'Temperaturwechsel­beständigkeitsprüfung', 'he' => 'בדיקת הלם תרמי'],
            ['en' => 'Glass grain (particle) hydrolytic resistance test', 'tr' => 'Cam tanesi (partikül) hidrolitik direnç testi', 'zh' => '玻璃颗粒耐水性测试', 'es' => 'Ensayo de resistencia hidrolítica del granulado de vidrio (partículas)', 'ru' => 'Испытание гидролитической стойкости стеклянной крошки (частиц)', 'fr' => 'Essai de résistance hydrolytique du verre en grains (particules)', 'pl' => 'Badanie odporności hydrolitycznej rozdrobnionego szkła (cząstek)', 'de' => 'Prüfung der hydrolytischen Beständigkeit des Glasgrießes (Partikel)', 'he' => 'בדיקת עמידות הידרוליטית של גרגרי זכוכית (חלקיקים)'],
            ['en' => 'Stress (annealing) test', 'tr' => 'Gerilim (tavlama) testi', 'zh' => '应力（退火）测试', 'es' => 'Ensayo de tensiones (recocido)', 'ru' => 'Испытание на остаточные напряжения (отжиг)', 'fr' => 'Essai de contraintes (recuit)', 'pl' => 'Badanie naprężeń (odprężanie)', 'de' => 'Spannungsprüfung (Kühlung)', 'he' => 'בדיקת מאמצים (חישול)'],
            ['en' => 'Heavy metal release test', 'tr' => 'Ağır metal salınımı testi', 'zh' => '重金属溶出测试', 'es' => 'Ensayo de liberación de metales pesados', 'ru' => 'Испытание на выделение тяжёлых металлов', 'fr' => 'Essai de libération de métaux lourds', 'pl' => 'Badanie uwalniania metali ciężkich', 'de' => 'Schwermetallabgabe-Prüfung', 'he' => 'בדיקת שחרור מתכות כבדות'],
        ],
        'note' => ['en' => 'Confirm the exact test scope you need with our technical team.', 'tr' => 'İhtiyacınız olan tam test kapsamını teknik ekibimizle teyit edin.', 'zh' => '请与我们的技术团队确认您所需的具体测试范围。', 'es' => 'Confirme con nuestro equipo técnico el alcance exacto de los ensayos que necesita.', 'ru' => 'Уточните необходимый объём испытаний у нашей технической команды.', 'fr' => 'Confirmez l’étendue exacte des essais dont vous avez besoin avec notre équipe technique.', 'pl' => 'Zakres potrzebnych badań potwierdź z naszym zespołem technicznym.', 'de' => 'Stimmen Sie den genauen Prüfumfang mit unserem technischen Team ab.', 'he' => 'אנא אשרו מול הצוות הטכני שלנו את היקף הבדיקות הנדרש לכם.'],
