/**
 * Distribütörlük sayfası içeriği (8 dil). Dünya genelinde distribütör arıyoruz.
 */
function content_distributors(): array
{
    return [
        'lead' => ['en' => 'Partner with Redex Glass in your market', 'tr' => 'Kendi pazarınızda Redex Glass ile ortak olun', 'zh' => '在您的市场与 Redex Glass 携手合作', 'es' => 'Colabore con Redex Glass en su mercado', 'ru' => 'Станьте партнёром Redex Glass на вашем рынке', 'fr' => 'Devenez partenaire de Redex Glass sur votre marché', 'pl' => 'Zostań partnerem Redex Glass na swoim rynku', 'de' => 'Werden Sie Redex-Glass-Partner in Ihrem Markt', 'he' => 'שותפות עם Redex Glass בשוק שלכם'],
        'intro' => ['en' => 'We are expanding our global network and are looking for distributors in every region of the world. If you understand your local pharmaceutical, cosmetic or packaging market, we want to build a lasting partnership with you.', 'tr' => 'Küresel ağımızı genişletiyor ve dünyanın her bölgesinde distribütör arıyoruz. Yerel ilaç, kozmetik veya ambalaj pazarınızı iyi biliyorsanız, sizinle kalıcı bir iş ortaklığı kurmak isteriz.', 'zh' => '我们正在拓展全球网络，面向世界各地区招募经销商。如果您熟悉当地的制药、化妆品或包装市场，我们愿与您建立长期合作关系。', 'es' => 'Estamos ampliando nuestra red global y buscamos distribuidores en todas las regiones del mundo. Si conoce su mercado local farmacéutico, cosmético o de envases, queremos construir con usted una colaboración duradera.', 'ru' => 'Мы расширяем свою глобальную сеть и ищем дистрибьюторов во всех регионах мира. Если вы хорошо знаете местный фармацевтический, косметический или упаковочный рынок, мы хотим построить с вами долгосрочное партнёрство.', 'fr' => 'Nous développons notre réseau mondial et recherchons des distributeurs dans chaque région du monde. Si vous connaissez votre marché local — pharmaceutique, cosmétique ou de l’emballage — nous souhaitons bâtir avec vous un partenariat durable.', 'pl' => 'Rozwijamy naszą globalną sieć i poszukujemy dystrybutorów w każdym regionie świata. Jeśli znasz swój lokalny rynek farmaceutyczny, kosmetyczny lub opakowaniowy, chcemy zbudować z Tobą trwałą współpracę.', 'de' => 'Wir bauen unser globales Netzwerk aus und suchen Vertriebspartner in allen Regionen der Welt. Wenn Sie Ihren lokalen Pharma-, Kosmetik- oder Verpackungsmarkt kennen, möchten wir mit Ihnen eine dauerhafte Partnerschaft aufbauen.', 'he' => 'אנו מרחיבים את הרשת הגלובלית שלנו ומחפשים מפיצים בכל אזור בעולם. אם אתם מכירים את השוק המקומי שלכם — תרופות, קוסמטיקה או אריזות — נשמח לבנות אתכם שותפות ארוכת טווח.'],
        'body' => ['en' => 'Since 2001 Redex Glass has produced amber and flint glass bottles and jars for pharmaceutical and cosmetic brands. We partner with strong local companies that can represent our quality, keep stock close to their customers, and grow the Redex name in their territory — backed by our factory, our catalogue and our technical team.', 'tr' => 'Redex Glass, 2001’den bu yana ilaç ve kozmetik markaları için amber ve flint cam şişeler ve kavanozlar üretiyor. Kalitemizi temsil edebilecek, stoğu müşterilerine yakın tutabilecek ve Redex adını kendi bölgesinde büyütebilecek güçlü yerel firmalarla iş birliği yaparız — fabrikamız, kataloğumuz ve teknik ekibimizle desteklenerek.', 'zh' => '自 2001 年以来，Redex Glass 为制药和化妆品品牌生产棕色及白料玻璃瓶罐。我们与实力雄厚的本地企业合作，由其代表我们的品质、在贴近客户的地方备货，并在其区域内发展 Redex 品牌——背后有我们的工厂、产品目录和技术团队作为支持。', 'es' => 'Desde 2001, Redex Glass fabrica frascos y tarros de vidrio ámbar y flint para marcas farmacéuticas y cosméticas. Colaboramos con empresas locales sólidas que puedan representar nuestra calidad, mantener stock cerca de sus clientes y hacer crecer la marca Redex en su territorio, con el respaldo de nuestra fábrica, nuestro catálogo y nuestro equipo técnico.', 'ru' => 'С 2001 года Redex Glass производит флаконы и банки из янтарного и бесцветного стекла для фармацевтических и косметических брендов. Мы сотрудничаем с сильными местными компаниями, которые представляют наше качество, держат запас рядом со своими клиентами и развивают бренд Redex на своей территории — при поддержке нашего завода, каталога и технической команды.', 'fr' => 'Depuis 2001, Redex Glass fabrique des flacons et pots en verre ambré et flint pour les marques pharmaceutiques et cosmétiques. Nous collaborons avec des entreprises locales solides, capables de représenter notre qualité, de tenir du stock au plus près de leurs clients et de développer la marque Redex sur leur territoire — avec le soutien de notre usine, de notre catalogue et de notre équipe technique.', 'pl' => 'Od 2001 roku Redex Glass produkuje butelki i słoiki ze szkła oranżowego i białego dla marek farmaceutycznych i kosmetycznych. Współpracujemy z silnymi lokalnymi firmami, które reprezentują naszą jakość, utrzymują zapas blisko klientów i rozwijają markę Redex na swoim terenie — przy wsparciu naszej fabryki, katalogu i zespołu technicznego.', 'de' => 'Seit 2001 produziert Redex Glass Flaschen und Tiegel aus Braun- und Weißglas für Pharma- und Kosmetikmarken. Wir arbeiten mit starken lokalen Unternehmen zusammen, die unsere Qualität vertreten, Ware nah beim Kunden bevorraten und die Marke Redex in ihrem Gebiet ausbauen — unterstützt von unserem Werk, unserem Katalog und unserem technischen Team.', 'he' => 'מאז 2001 מייצרת Redex Glass בקבוקים וצנצנות מזכוכית ענבר וזכוכית צלולה עבור מותגי תרופות וקוסמטיקה. אנו משתפים פעולה עם חברות מקומיות חזקות שמייצגות את האיכות שלנו, מחזיקות מלאי קרוב ללקוחותיהן ומפתחות את שם Redex באזורן — בגיבוי המפעל, הקטלוג והצוות הטכני שלנו.'],
        'offer_title' => ['en' => 'What we offer our distributors', 'tr' => 'Distribütörlerimize sunduklarımız', 'zh' => '我们为经销商提供', 'es' => 'Lo que ofrecemos a nuestros distribuidores', 'ru' => 'Что мы предлагаем дистрибьюторам', 'fr' => 'Ce que nous offrons à nos distributeurs', 'pl' => 'Co oferujemy naszym dystrybutorom', 'de' => 'Was wir unseren Vertriebspartnern bieten', 'he' => 'מה אנו מציעים למפיצים שלנו'],
        'offer' => [
            ['en' => 'Exclusive, territory-based distribution rights', 'tr' => 'Münhasır, bölge bazlı distribütörlük hakları', 'zh' => '独家、按区域划分的经销权', 'es' => 'Derechos de distribución exclusivos por territorio', 'ru' => 'Эксклюзивные права дистрибуции по территории', 'fr' => 'Droits de distribution exclusifs par territoire', 'pl' => 'Wyłączne prawa dystrybucji na danym terytorium', 'de' => 'Exklusive, gebietsbezogene Vertriebsrechte', 'he' => 'זכויות הפצה בלעדיות לפי טריטוריה'],
            ['en' => 'Competitive factory-direct pricing and dependable lead times', 'tr' => 'Rekabetçi fabrika-direkt fiyatlandırma ve güvenilir teslim süreleri', 'zh' => '具竞争力的工厂直供价格与可靠的交期', 'es' => 'Precios competitivos directos de fábrica y plazos de entrega fiables', 'ru' => 'Конкурентные цены напрямую с завода и надёжные сроки поставки', 'fr' => 'Des prix compétitifs directs usine et des délais fiables', 'pl' => 'Konkurencyjne ceny prosto z fabryki i pewne terminy realizacji', 'de' => 'Wettbewerbsfähige Direktpreise ab Werk und verlässliche Lieferzeiten', 'he' => 'מחירים תחרותיים ישירות מהמפעל וזמני אספקה אמינים'],
            ['en' => 'Full product catalogue, samples and technical documentation', 'tr' => 'Tam ürün kataloğu, numuneler ve teknik dokümantasyon', 'zh' => '完整的产品目录、样品及技术文件', 'es' => 'Catálogo completo de productos, muestras y documentación técnica', 'ru' => 'Полный каталог продукции, образцы и техническая документация', 'fr' => 'Catalogue produits complet, échantillons et documentation technique', 'pl' => 'Pełny katalog produktów, próbki i dokumentacja techniczna', 'de' => 'Vollständiger Produktkatalog, Muster und technische Unterlagen', 'he' => 'קטלוג מוצרים מלא, דוגמיות ותיעוד טכני'],
            ['en' => 'Marketing support and direct access to our export team', 'tr' => 'Pazarlama desteği ve ihracat ekibimize doğrudan erişim', 'zh' => '营销支持及与出口团队的直接对接', 'es' => 'Apoyo de marketing y acceso directo a nuestro equipo de exportación', 'ru' => 'Маркетинговая поддержка и прямой доступ к нашей экспортной команде', 'fr' => 'Un soutien marketing et un accès direct à notre équipe export', 'pl' => 'Wsparcie marketingowe i bezpośredni kontakt z naszym zespołem eksportu', 'de' => 'Marketingunterstützung und direkter Draht zu unserem Exportteam', 'he' => 'תמיכה שיווקית וגישה ישירה לצוות הייצוא שלנו'],
